-- 197: Original BrillaPrep WASSCE BrillaPrep transitional Basketry beta content blueprint questions, part 5.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_197_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_197_guard;
INSERT INTO _migration_197_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_basketry_b004_017' AND NOT (q.topic_id IS 'topic_was_basketry_b004_4' AND q.subject_id IS 'subj_wassce_basketry' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What distinguishes pairing or twining from simple one-strand randing?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Two weavers cross around successive stakes as the course advances","B. One strand passes alternately over and under successive stakes","C. A bundled core is wrapped and stitched to the preceding round","D. Broad strips cross diagonally without twisting around upright stakes"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Pairing uses two active strands that exchange position around the uprights, producing a locking course that can strengthen starts, borders and changes in the basket form. Therefore the correct answer is A: Two weavers cross around successive stakes as the course advances.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_basketry_b004_4' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_basketry_b004_017' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_197_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_basketry_b004_018' AND NOT (q.topic_id IS 'topic_was_basketry_b004_4' AND q.subject_id IS 'subj_wassce_basketry' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why is an odd number of stakes useful for continuous over-one-under-one randing?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. An even stake count normally shifts the sequence after each continuous round","B. Removing a stake at the end of a round is the normal way to maintain alternation","C. Successive rounds reverse the over-under relationship at each stake","D. Stake number matters only to rim decoration and not continuous randing"]' AND q.correct_answer IS 'C' AND q.explanation IS 'With an odd stake count, returning to the starting area shifts the sequence, so the next round alternates correctly instead of stacking identical crossings above one another. Therefore the correct answer is C: Successive rounds reverse the over-under relationship at each stake.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_basketry_b004_4' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_basketry_b004_018' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_197_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_basketry_b004_019' AND NOT (q.topic_id IS 'topic_was_basketry_b004_4' AND q.subject_id IS 'subj_wassce_basketry' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the likely effect of pulling one side’s weavers much tighter than the other side’s?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The basket form will distort toward the tighter area","B. A strong round border can correct accumulated wall distortion at the finishing stage","C. Unequal tension changes gaps but has little influence on the basket profile","D. The tighter side expands farther because tension pushes its stakes outward"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Unequal tension changes spacing and bends the stakes asymmetrically, so regular checking and gradual correction are needed to maintain the intended diameter, profile and alignment. Therefore the correct answer is A: The basket form will distort toward the tighter area.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_basketry_b004_4' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_basketry_b004_019' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_197_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_basketry_b004_020' AND NOT (q.topic_id IS 'topic_was_basketry_b004_4' AND q.subject_id IS 'subj_wassce_basketry' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What form develops when half-knots are repeated from the same side in macrame?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The knots align as a straight row of double half hitches along a separate carrier cord","B. The working cords rotate around the fillers to form a spiral sinnet","C. The repeated half-knots secure folded cords to a support in the same pattern as lark''s-head mounting","D. The alternating halves settle into a flat square-knot sinnet without directional twist"]' AND q.correct_answer IS 'B' AND q.explanation IS 'A half-knot is one side of a square knot. Repeating that same side makes the working cords advance around the filler cords, creating the characteristic twisted or spiral sinnet instead of a flat square-knot band. Therefore the correct answer is B: The working cords rotate around the fillers to form a spiral sinnet.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_basketry_b004_4' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_basketry_b004_020' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_basketry_b004_017', 'topic_was_basketry_b004_4', 'subj_wassce_basketry', 'exam_wassce', NULL, NULL, 'What distinguishes pairing or twining from simple one-strand randing?', 'multiple_choice', NULL, '["A. Two weavers cross around successive stakes as the course advances","B. One strand passes alternately over and under successive stakes","C. A bundled core is wrapped and stitched to the preceding round","D. Broad strips cross diagonally without twisting around upright stakes"]', 'A', 'Pairing uses two active strands that exchange position around the uprights, producing a locking course that can strengthen starts, borders and changes in the basket form. Therefore the correct answer is A: Two weavers cross around successive stakes as the course advances.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_basketry_b004_4', 'Identify', 'AO2', NULL, NULL, 'board_waec');
