INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_basketry_b004_019', 'topic_was_basketry_b004_4', 'subj_wassce_basketry', 'exam_wassce', NULL, NULL, 'What is the likely effect of pulling one side’s weavers much tighter than the other side’s?', 'multiple_choice', NULL, '["A. The basket form will distort toward the tighter area","B. A strong round border can correct accumulated wall distortion at the finishing stage","C. Unequal tension changes gaps but has little influence on the basket profile","D. The tighter side expands farther because tension pushes its stakes outward"]', 'A', 'Unequal tension changes spacing and bends the stakes asymmetrically, so regular checking and gradual correction are needed to maintain the intended diameter, profile and alignment. Therefore the correct answer is A: The basket form will distort toward the tighter area.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_basketry_b004_4', 'Identify', 'AO1', NULL, NULL, 'board_waec');
